class Solution {
public:
    string boldWords(vector<string>& words, string s) {
        int n = s.size();
        vector<bool> bold(n, false);
        for (const string& word : words) {
            size_t pos = s.find(word);
            while (pos != string::npos) {
                for (size_t i = pos; i < pos + word.size(); ++i) {
                    bold[i] = true;
                }
                pos = s.find(word, pos + 1);
            }
        }
        string answer;
        for (int i = 0; i < n;) {
            if (!bold[i]) {
                answer += s[i++];
                continue;
            }
            answer += "<b>";
            while (i < n && bold[i]) {
                answer += s[i++];
            }
            answer += "</b>";
        }
        return answer;
    }
};
